685	// ParseManifest decodes data as a non-empty JSON array holding exactly the
686	// four required fields batch, product, quantity and unit per element. The
687	// three text fields must be JSON strings that are not blank after trimming;
688	// quantity must be a JSON integer (no strings, fractions or exponents) in
689	// the range 1..MaxQuantity. An empty file, empty array, non-array document
690	// or any malformed record is rejected. The manifest bytes are never written.
691	func ParseManifest(data []byte) ([]Input, error) {
692		trimmed := bytes.TrimSpace(data)
693		if len(trimmed) == 0 {
694			return nil, errors.New("manifest file is empty")
695		}
696		if trimmed[0] != '[' {
697			return nil, errors.New("manifest must be a non-empty JSON array of records")
698		}
699	
700		var elems []json.RawMessage
701		dec := json.NewDecoder(bytes.NewReader(data))
702		if err := dec.Decode(&elems); err != nil {
703			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
704		}
705		var extra json.RawMessage
706		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
707			if err == nil {
708				return nil, errors.New("manifest has unexpected data after the array")
709			}
710			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
711		}
712		if len(elems) == 0 {
713			return nil, errors.New("manifest must contain at least one record")
714		}
715	
716		inputs := make([]Input, 0, len(elems))
717		for i, raw := range elems {
718			pos := i + 1
719			in, err := parseManifestRecord(raw)
720			if err != nil {
721				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
722			}
723			inputs = append(inputs, in)
724		}
725		return inputs, nil
726	}
727	
728	// batchRecordFields are the only members a batch record may carry, in the
729	// registry file and in an import manifest alike.
730	var batchRecordFields = map[string]struct{}{
731		"batch": {}, "product": {}, "quantity": {}, "unit": {},
732	}
733	
734	// parseManifestRecord validates one manifest element: it must be a JSON
735	// object with exactly the four required keys, text fields as non-blank,
736	// valid UTF-8 strings and quantity as a strict JSON integer. The members
737	// are scanned with parseObjectFields (strict key decoding, duplicates kept
738	// visible) rather than a lenient map unmarshal, so malformed key or value
739	// bytes cannot be silently replaced with U+FFFD. Whatever makes the record
740	// fail — an unknown, duplicated or case-mismatched field included — the
741	// returned Input carries the normalized batch id whenever exactly one
742	// "batch" member holds valid, non-blank text, so the caller can name the
743	// batch in the error; otherwise it stays empty.
744	func parseManifestRecord(raw json.RawMessage) (Input, error) {
745		var in Input
746		members, err := parseObjectFields(raw)
747		if err != nil {
748			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
749		}
750		// Attach the batch id to whatever error this record raises, but only when
751		// it is unambiguous: exactly one "batch" member (compared after JSON key
752		// decoding, so an escaped respelling counts as the same field) carrying a
753		// JSON string whose decoded text is valid UTF-8 and non-blank once
754		// trimmed. A missing, duplicated, mistyped, blank or malformed "batch"
755		// member leaves the id out — never a U+FFFD substitution, and never one
756		// of two duplicate values picked arbitrarily, even when both are equal.
757		// Where the "batch" member sits relative to the offending field does not
758		// matter.
759		if countField(members, "batch") == 1 {
760			if rawID, ok := findField(members, "batch"); ok {
761				if id, idErr := unmarshalStringStrict(rawID); idErr == nil {
762					if normalized, normErr := NormalizeField(id); normErr == nil {
763						in.Batch = normalized
764					}
765				}
766			}
767		}
768		fields := make(map[string]json.RawMessage, len(members))
769		for _, f := range members {
770			if _, ok := batchRecordFields[f.key]; !ok {
771				return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", f.key)
772			}
773			if _, dup := fields[f.key]; dup {
774				return in, fmt.Errorf("record lists field %q more than once", f.key)
775			}
776			fields[f.key] = f.value
777		}
778	
779		textField := func(name string) (string, error) {
780			value, ok := fields[name]
781			if !ok {
782				return "", fmt.Errorf("missing required field %q", name)
783			}
784			if trimmed := bytes.TrimSpace(value); len(trimmed) == 0 || trimmed[0] != '"' {
785				return "", fmt.Errorf("field %q must be a JSON string", name)
786			}
787			text, decodeErr := unmarshalStringStrict(value)
788			if errors.Is(decodeErr, errStringEncoding) {
789				return "", &EncodingError{Field: name}
790			}
791			if decodeErr != nil {
792				return "", fmt.Errorf("field %q must be a JSON string", name)
793			}
794			normalized, normErr := NormalizeField(text)
795			if normErr != nil {
796				return "", fmt.Errorf("field %q must not be blank: %w", name, normErr)
797			}
798			return normalized, nil
799		}
800	
801		in.Batch, err = textField("batch")
802		if err != nil {
803			return in, err
804		}
805		in.Product, err = textField("product")
806		if err != nil {
807			return in, err
808		}
809		in.Unit, err = textField("unit")
810		if err != nil {
811			return in, err
812		}
813		quantityRaw, ok := fields["quantity"]
814		if !ok {
815			return in, errors.New("missing required field \"quantity\"")
816		}
817		in.Quantity, err = parseManifestQuantity(bytes.TrimSpace(quantityRaw))
818		if err != nil {
819			return in, err
820		}
821		return in, nil
822	}
823	
824	// parseManifestQuantity accepts exactly a strict JSON integer token in the
825	// range 1..MaxQuantity. Strings, signs, fractions, exponents, leading zeros
826	// and out-of-range values are rejected instead of silently rounded.
827	func parseManifestQuantity(token []byte) (int64, error) {
828		if len(token) == 0 || token[0] < '0' || token[0] > '9' {
829			return 0, fmt.Errorf("field %q must be a JSON integer between 1 and %d", "quantity", MaxQuantity)
830		}
831		for _, c := range token {
832			if c < '0' || c > '9' {
833				return 0, fmt.Errorf("field %q must be a JSON integer without sign, fraction or exponent", "quantity")
834			}
835		}
836		if len(token) > 1 && token[0] == '0' {
837			return 0, errors.New("field \"quantity\" must be a JSON integer without leading zeros")
838		}
839		value, err := strconv.ParseInt(string(token), 10, 64)
840		if err != nil {
841			return 0, fmt.Errorf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)
842		}
843		if value == 0 {
844			return 0, errors.New("field \"quantity\" must be greater than zero")
845		}
846		return value, nil
847	}
848	
849	// ImportResult is one entry of an Import outcome: the normalized record in
850	// manifest order plus whether it was newly created or already present.
851	type ImportResult struct {
852		Batch   Batch
853		Created bool
854	}
855	
856	// validateManifestInput applies the same effective-value rules to one
857	// directly submitted record that Register enforces for single entries and
858	// parseManifestRecord enforces for file records: the three text fields must
859	// be valid UTF-8 and must not be empty strings, and quantity must lie in
860	// 1..MaxQuantity. Text is checked verbatim — direct submissions get no
861	// whitespace trimming or case folding (the command-line entry normalizes
862	// before constructing the Input), so whitespace-only text is accepted as
863	// ordinary non-empty text. pos is the record's 1-based position in this
864	// submission. The returned *ManifestRecordError names the offending field
865	// in its reason and cites the batch id only when that id is itself
866	// non-empty, valid UTF-8 text; it is never invented or substituted when the
867	// batch field is empty or malformed.
868	func validateManifestInput(in Input, pos int) error {
869		batchID := ""
870		if in.Batch != "" && utf8.ValidString(in.Batch) {
871			batchID = in.Batch
872		}
873		textFields := []struct {
874			field, value string
875		}{
876			{"batch", in.Batch}, {"product", in.Product}, {"unit", in.Unit},
877		}
878		for _, tv := range textFields {
879			if !utf8.ValidString(tv.value) {
880				// batchID is already "" when the batch field itself is the
881				// malformed one, so it is safe to attach it unconditionally.
882				return &ManifestRecordError{Position: pos, Batch: batchID, Reason: (&EncodingError{Field: tv.field}).Error()}
883			}
884		}
885		for _, tv := range textFields {
886			if tv.value == "" {
887				return &ManifestRecordError{Position: pos, Batch: batchID, Reason: fmt.Sprintf("field %q must not be empty", tv.field)}
888			}
889		}
890		if in.Quantity <= 0 {
891			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: `field "quantity" must be greater than zero`}
892		}
893		if in.Quantity > MaxQuantity {
894			return &ManifestRecordError{Position: pos, Batch: batchID,
895				Reason: fmt.Sprintf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)}
896		}
897		return nil
898	}
899	
900	// Import validates every record of inputs before appending anything: the
901	// whole manifest fails if any record carries invalid UTF-8, an empty text
902	// field or a quantity outside 1..MaxQuantity — whether its batch id is new,
903	// already stored or seen earlier in this submission — or if any record
904	// conflicts with a stored record or with an earlier manifest record, and reg
905	// is left untouched on error. Directly submitted text is kept verbatim. New
906	// batch ids are appended in first-occurrence order; an id already stored or
907	// introduced earlier in the same manifest is confirmed as a duplicate only
908	// when product, quantity and unit all match. Results come back in manifest
909	// order; Created is false for duplicates.
910	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
911		if reg.Version != FormatVersion {
912			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
913		}
914		if len(inputs) == 0 {
915			return nil, errors.New("manifest must contain at least one record")
916		}
917		// Reject malformed text and non-effective values before touching
918		// anything; this covers records handed in directly by Go callers the
919		// same way ParseManifest covers file records, so a blank text field or a
920		// non-positive quantity can never reach the new/duplicate/conflict logic
921		// below and end up in a file the reader would refuse. Text is checked
922		// verbatim: direct submissions get no trimming or case folding (only the
923		// command-line entry normalizes, before building the Input).
924		for i, in := range inputs {
925			if err := validateManifestInput(in, i+1); err != nil {
926				return nil, err
927			}
928		}
929	
930		// Work on a copy: a rejected manifest must never partially land in reg.
931		working := append([]Batch(nil), reg.Batches...)
932		indexByID := make(map[string]int, len(working))
933		for i, b := range working {
934			indexByID[b.Batch] = i
935		}
936		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
937	
938		out := make([]ImportResult, len(inputs))
939		for i, in := range inputs {
940			pos := i + 1
941			if idx, known := indexByID[in.Batch]; known {
942				existing := working[idx]
943				diffs := diffFields(existing, in)
944				if len(diffs) > 0 {
945					if prev, inManifest := firstPos[in.Batch]; inManifest {
946						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
947					}
948					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
949				}
950				out[i] = ImportResult{Batch: existing, Created: false}
951				continue
952			}
953			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
954			working = append(working, b)
955			indexByID[in.Batch] = len(working) - 1
956			firstPos[in.Batch] = pos
957			out[i] = ImportResult{Batch: b, Created: true}
958		}
959	
960		reg.Batches = working
961		return out, nil
962	}
963	
964	// diffFields lists the members of product, quantity and unit in which in
965	// differs from existing, in that fixed order.
966	func diffFields(existing Batch, in Input) []string {
967		var diffs []string
968		if existing.Product != in.Product {
969			diffs = append(diffs, "product")
970		}
971		if existing.Quantity != in.Quantity {
972			diffs = append(diffs, "quantity")
973		}
974		if existing.Unit != in.Unit {
975			diffs = append(diffs, "unit")
976		}
977		return diffs
978	}
979	
980	// Register adds in to reg, or confirms the identical record already stored
981	// under the same batch id. A batch id held by a record differing in product,
982	// quantity or unit produces a *ConflictError and leaves reg untouched. The
983	// zero Outcome is returned together with the error.
984	func Register(reg *Registry, in Input) (Outcome, error) {
985		if reg.Version != FormatVersion {
986			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
987		}
988		if in.Batch == "" || in.Product == "" || in.Unit == "" {
989			return Outcome{}, errors.New("batch, product and unit must be non-empty")
990		}
991		for _, tv := range []struct{ field, value string }{
992			{"batch", in.Batch}, {"product", in.Product}, {"unit", in.Unit},
993		} {
994			if !utf8.ValidString(tv.value) {
995				return Outcome{}, &EncodingError{Field: tv.field}
996			}
997		}
998		if in.Quantity <= 0 || in.Quantity > MaxQuantity {
999			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
1000		}
1001		for _, b := range reg.Batches {
1002			if b.Batch != in.Batch {
1003				continue
1004			}
1005			var diffs []string
1006			if b.Product != in.Product {
1007				diffs = append(diffs, "product")
1008			}
1009			if b.Quantity != in.Quantity {
1010				diffs = append(diffs, "quantity")
1011			}
1012			if b.Unit != in.Unit {
1013				diffs = append(diffs, "unit")
1014			}
1015			if len(diffs) > 0 {
1016				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
1017			}
1018			return Outcome{Batch: b, Created: false}, nil
1019		}
1020		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
1021		reg.Batches = append(reg.Batches, b)
1022		return Outcome{Batch: b, Created: true}, nil
1023	}
1024	
1025	// validateForSave checks every record of reg against the rules Load enforces,
1026	// so a hand-assembled registry cannot be persisted in a shape the reader
1027	// would refuse. Records are checked in order and the first violation is
1028	// reported as a *FormatError naming the 1-based record position, the field
1029	// and the reason; the batch id is attached only when it is itself non-empty,
1030	// valid UTF-8 text — never a U+FFFD substitution for a malformed id. A batch
1031	// id seen twice is reported as a *DuplicateIDError carrying both 1-based
1032	// positions, even when the two records are identical: Save persists records,
1033	// it never confirms duplicates or merges them. Text is checked verbatim —
1034	// no trimming, no case folding — and reg is never modified.
1035	func validateForSave(reg *Registry) error {
1036		seen := make(map[string]int, len(reg.Batches))
1037		for i, b := range reg.Batches {
1038			pos := i + 1
1039			batchID := ""
1040			if b.Batch != "" && utf8.ValidString(b.Batch) {
1041				batchID = b.Batch
1042			}
1043			for _, tv := range []struct{ field, value string }{
1044				{"batch", b.Batch}, {"product", b.Product}, {"unit", b.Unit},
1045			} {
1046				if !utf8.ValidString(tv.value) {
1047					return &FormatError{Position: pos, Batch: batchID, Field: tv.field,
1048						Reason: "must be valid UTF-8 text: malformed bytes are rejected instead of being replaced with U+FFFD"}
1049				}
1050				if tv.value == "" {
1051					return &FormatError{Position: pos, Batch: batchID, Field: tv.field, Reason: "must not be empty"}
1052				}
1053			}
1054			if b.Quantity < 1 || b.Quantity > MaxQuantity {
1055				return &FormatError{Position: pos, Batch: batchID, Field: "quantity",
1056					Reason: fmt.Sprintf("must be between 1 and %d", MaxQuantity)}
1057			}
1058			if first, dup := seen[b.Batch]; dup {
1059				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
1060			}
1061			seen[b.Batch] = pos
1062		}
1063		return nil
1064	}
1065	
1066	// Save atomically writes reg to path, replacing the file only after the new
1067	// content is fully on disk so an existing registry stays usable on failure.
1068	// Records are serialized in their current order; the file is created with
1069	// 0644 permissions or, when replacing an existing file, with its permissions.
1070	//
1071	// Every record must satisfy the same effective-value rules Load enforces, so
1072	// a registry saved successfully always reads back: batch, product and unit
1073	// must be non-empty valid UTF-8 text (kept verbatim — no trimming or case
1074	// folding, so whitespace-only text is ordinary non-empty text), quantity
1075	// must lie in 1..MaxQuantity, and batch ids must be unique under exact
1076	// byte-for-byte comparison, two identical records included. Any violation
1077	// rejects the whole save before anything is written: an existing target
1078	// keeps its bytes and modification time, a missing target stays missing and
1079	// no temporary file is left behind. A nil or empty Batches is a legal empty
1080	// registry and is written as "batches": [] without touching reg itself.
1081	func Save(path string, reg *Registry) error {
1082		if reg.Version != FormatVersion {
1083			return fmt.Errorf("cannot write registry format version %d", reg.Version)
1084		}
1085		if err := validateForSave(reg); err != nil {
1086			return fmt.Errorf("cannot save registry %q: %w", path, err)
1087		}
1088		mode := os.FileMode(0o644)
1089		if info, err := os.Stat(path); err == nil {
1090			mode = info.Mode().Perm()
1091		} else if !errors.Is(err, fs.ErrNotExist) {
1092			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
1093		}
1094	
1095		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
1096			return fmt.Errorf("cannot save registry %q: %w", path, err)
1097		}
1098	
1099		// Encode a shallow copy so a nil Batches marshals as [] (null would not
1100		// read back) without mutating the caller's registry.
1101		out := *reg
1102		if out.Batches == nil {
1103			out.Batches = []Batch{}
1104		}
1105		var buf bytes.Buffer
1106		enc := json.NewEncoder(&buf)
1107		enc.SetEscapeHTML(false)
1108		enc.SetIndent("", "  ")
1109		if err := enc.Encode(&out); err != nil {
1110			return fmt.Errorf("cannot encode registry %q: %w", path, err)
1111		}
1112	
1113		tmp, err := os.CreateTemp(filepath.Dir(path), ".govflow-registry-*.tmp")
1114		if err != nil {
1115			return fmt.Errorf("cannot save registry %q: %w", path, err)
1116		}
1117		tmpName := tmp.Name()
1118		abort := func(cause error) error {
1119			tmp.Close()
1120			os.Remove(tmpName)
1121			return fmt.Errorf("cannot save registry %q: %w", path, cause)
1122		}
1123		if _, err := tmp.Write(buf.Bytes()); err != nil {
1124			return abort(err)
1125		}
1126		if err := tmp.Chmod(mode); err != nil {
1127			return abort(err)
1128		}
1129		if err := tmp.Sync(); err != nil {
1130			return abort(err)
1131		}
1132		if err := tmp.Close(); err != nil {
1133			os.Remove(tmpName)
1134			return fmt.Errorf("cannot save registry %q: %w", path, err)
1135		}
1136		if err := os.Rename(tmpName, path); err != nil {
1137			os.Remove(tmpName)
1138			return fmt.Errorf("cannot save registry %q: %w", path, err)
1139		}
1140		return nil
1141	}
1142

