type quantityFlaw int

const (
    flawNone quantityFlaw = iota
    flawNotDigitLed      // empty or first byte not 0-9
    flawNonDigit         // digit-led but a later byte is not 0-9
    flawLeadingZero      // "0" followed by more digits
    flawOverflow         // digits but above int64 max
    flawZero             // the integer 0
)

// classifyQuantityToken examines a raw JSON token...
func classifyQuantityToken(token []byte) (int64, quantityFlaw) {
    if len(token) == 0 || token[0] < '0' || token[0] > '9' {
        return 0, flawNotDigitLed
    }
    for _, c := range token {
        if c < '0' || c > '9' {
            return 0, flawNonDigit
        }
    }
    if len(token) > 1 && token[0] == '0' {
        return 0, flawLeadingZero
    }
    value, err := strconv.ParseInt(string(token), 10, 64)
    if err != nil {
        return 0, flawOverflow
    }
    if value == 0 {
        return 0, flawZero
    }
    return value, flawNone
}
```

