// unambiguousBatchID returns the record's batch id for error messages when
// exactly one "batch" member carries a decodable JSON string; normalize
// trims and rejects blank ids (manifest) while false keeps the id verbatim
// (registry).
func unambiguousBatchID(fields []objectField, normalize bool) string {
    if countField(fields, "batch") != 1 {
        return ""
    }
    rawID, ok := findField(fields, "batch")
    if !ok {
        return ""
    }
    id, err := unmarshalStringStrict(rawID)
    if err != nil {
        return ""
    }
    if normalize {
        id, err = NormalizeField(id)
        if err != nil {
            return ""
        }
    }
    return id
}
```

