// scanRecordMembers validates member names against the batch record schema.
// It reports the first duplicated field name (in member order) and the first
// problem in member order, where each member is checked unknown-then-duplicate.
func scanRecordMembers(fields []objectField) (firstDuplicate string, firstProblemField string, firstProblemKind memberFlaw) {
    seen := make(map[string]struct{}, len(fields))
    haveProblem := false
    for _, f := range fields {
        _, known := batchRecordFields[f.key]
        _, dup := seen[f.key]
        if dup && firstDuplicate == "" {
