            case !known:
                firstProblemField, firstProblemKind, haveProblem = f.key, flawUnknownField, true
            case dup:
                firstProblemField, firstProblemKind, haveProblem = f.key, flawDuplicateField, true
            }
        }
        seen[f.key] = struct{}{}
    }
    return
}
