```go
// unambiguousBatchID extracts a record's batch id for error messages, but
// only when it is uniquely determined: exactly one "batch" member carrying a
// JSON string whose decoded text is valid UTF-8. When normalize is true
// (import manifests) the id is also trimmed and must not be blank; the
// registry file keeps the stored id verbatim. A missing, duplicated,
// mistyped or malformed "batch" member yields "" — no id is ever invented,
// and never a U+FFFD substitution.
func unambiguousBatchID(fields []objectField, normalize bool) string {
	if countField(fields, "batch") != 1 {
		return ""
	}
	rawID, ok := findField(fields, "batch")
	if !ok {
		return ""
	}
	id, err := unmarshalStringStrict(rawID)
	if err != nil {
		return ""
	}
	if normalize {
		id, err = NormalizeField(id)
		if err != nil {
			return ""
		}
	}
	return id
}
