// duplicateField returns the first field name appearing more than once.
func duplicateField(fields []objectField) (string, bool) {
	seen := make(map[string]struct{}, len(fields))
	for _, f := range fields {
		if _, dup := seen[f.key]; dup {
			return f.key, true
		}
		seen[f.key] = struct{}{}
	}
	return "", false
}

